def today_korean_date() -> str:
    weekdays = ["월", "화", "수", "목", "금", "토", "일"]
    d = date.today()
    return f"{d.year}. {d.month}. {d.day}. ({weekdays[d.weekday()]})"


def format_quote_card_text(text: str) -> str:
    formatted = text

    # 문장 자체는 바꾸지 않고, 긴 문장만 의미 단위에서 줄바꿈
    preferred_breaks = [
        ", 너도",
        ". 삶이",
        ", 삶이",
        " 그것으로 충분하다.",
        " 한 구절을 보탤 수 있다는 것.",
    ]
    if len(formatted) >= 26:
        for token in preferred_breaks:
            if token in formatted:
                if token.startswith(","):
                    formatted = formatted.replace(token, token[0] + "<br>" + token[2:], 1)
                elif token.startswith("."):
                    formatted = formatted.replace(token, token[0] + "<br>" + token[2:], 1)
                else:
                    formatted = formatted.replace(token, "<br>" + token.strip(), 1)
                break

    return formatted


